rng=np.random.default_rng(613)
def sample(n):
 X=np.zeros((n,20)); X[:,0]=rng.uniform(-3,4,n); X[:,1:10]=rng.integers(0,2,(n,9)); X[:,10:]=rng.uniform(0,10,(n,10)); return X
C=np.array([0]+[.5]*9+[5]*10); S=np.array([2]+[.5]*9+[3]*10)
knots={0:[-2,0,2]}
for i in range(10,20): knots[i]=[2,4,6,8]
pairs=[(i,j) for i in range(20) for j in range(i+1,20)]
def features(X,level):
 Z=(X-C)/S
 cols=[np.ones(len(X))]
 cols.extend([Z[:,i] for i in range(20)])
 if level>=1:
  for i,ks in knots.items():
   for k in ks: cols.append(np.maximum(X[:,i]-k,0)/S[i])
 if level>=2:
  for i,j in pairs: cols.append(Z[:,i]*Z[:,j])
 if level>=3:
  for i in [0]+list(range(10,20)):
   for j in range(i+1,20):
    if j>=10:
     cols.append(np.maximum(X[:,i]-C[i],0)/S[i]*np.maximum(X[:,j]-C[j],0)/S[j])
 return np.array(cols).T
A=sample(9000); B=sample(3000); ya=predict(A); yb=predict(B)
print('y sd',yb.std())
for level in range(4):
 F=features(A,level); G=features(B,level)
 coef=np.linalg.lstsq(F,ya,rcond=1e-8)[0]
 er=yb-G@coef
 print(level,F.shape,'train',np.sqrt(np.mean((ya-F@coef)**2)),'test rmse',np.sqrt(np.mean(er*er)),'mae',np.mean(np.abs(er)),'q',np.quantile(np.abs(er),[.5,.9,.99]),'bias',er.mean())

